<template><div><PageHeader title="请假审批" description="处理请假待办并查询审批历史"><el-button @click="typeVisible=true">请假类型</el-button><el-button type="primary" :icon="Refresh" @click="load">刷新</el-button></PageHeader><el-tabs v-model="tab"><el-tab-pane label="审批待办" name="pending"><section class="panel"><el-table v-loading="loading" :data="rows"><el-table-column prop="request_no" label="申请单号" min-width="180"/><el-table-column prop="employee_id" label="员工 ID"/><el-table-column prop="leave_type_id" label="类型 ID"/><el-table-column prop="start_date" label="开始日期"/><el-table-column prop="end_date" label="结束日期"/><el-table-column prop="days" label="天数"/><el-table-column prop="reason" label="事由" min-width="180"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button link @click="showDetail(row)">详情</el-button><el-button link type="success" @click="openApprove(row,'APPROVE')">通过</el-button><el-button link type="danger" @click="openApprove(row,'REJECT')">驳回</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无待审批申请"/></section></el-tab-pane><el-tab-pane label="审批历史" name="history"><section class="panel"><el-table :data="history"><el-table-column prop="request_no" label="申请单号"/><el-table-column prop="employee_id" label="员工 ID"/><el-table-column prop="days" label="天数"/><el-table-column prop="status" label="状态"/><el-table-column label="审批意见"><template #default="{row}">{{row.approval?.comment||'-'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="showDetail(row)">查看详情</el-button></template></el-table-column></el-table></section></el-tab-pane></el-tabs><el-dialog v-model="detailVisible" title="请假申请详情" width="560"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="申请单号">{{detail.request_no}}</el-descriptions-item><el-descriptions-item label="员工 ID">{{detail.employee_id}}</el-descriptions-item><el-descriptions-item label="日期">{{detail.start_date}} 至 {{detail.end_date}}</el-descriptions-item><el-descriptions-item label="时长">{{detail.days}} 天</el-descriptions-item><el-descriptions-item label="状态">{{detail.status}}</el-descriptions-item><el-descriptions-item label="事由">{{detail.reason}}</el-descriptions-item><el-descriptions-item label="审批意见" :span="2">{{detail.approval?.comment||'-'}}</el-descriptions-item></el-descriptions></el-dialog><el-dialog v-model="approveVisible" :title="action==='APPROVE'?'通过申请':'驳回申请'" width="460"><el-input v-model="comment" type="textarea" :rows="4" placeholder="审批意见（可选）"/><template #footer><el-button @click="approveVisible=false">取消</el-button><el-button :type="action==='APPROVE'?'success':'danger'" :loading="saving" @click="submit">确认</el-button></template></el-dialog><el-dialog v-model="typeVisible" title="请假类型" width="650"><div class="dialog-toolbar"><el-button type="primary" size="small" @click="newType">新增类型</el-button></div><el-table :data="types"><el-table-column prop="name" label="名称"/><el-table-column prop="code" label="编码"/><el-table-column prop="days_per_year" label="年度额度"/></el-table></el-dialog><el-dialog v-model="newTypeVisible" title="新增请假类型" width="420"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="typeForm.name"/></el-form-item><el-form-item label="编码"><el-input v-model="typeForm.code"/></el-form-item><el-form-item label="年度额度"><el-input-number v-model="typeForm.days_per_year" :min="0"/></el-form-item></el-form><template #footer><el-button @click="newTypeVisible=false">取消</el-button><el-button type="primary" @click="saveType">保存</el-button></template></el-dialog></div></template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{Refresh}from'@element-plus/icons-vue';import PageHeader from'../components/PageHeader.vue';import{leaveApi}from'../api';const tab=ref('pending'),rows=ref([]),history=ref([]),types=ref([]),detail=ref(null),loading=ref(false),saving=ref(false),approveVisible=ref(false),detailVisible=ref(false),typeVisible=ref(false),newTypeVisible=ref(false),current=ref(null),action=ref('APPROVE'),comment=ref('');const typeForm=reactive({name:'',code:'',days_per_year:null});async function load(){loading.value=true;try{const[p,h,t]=await Promise.all([leaveApi.pending(),leaveApi.review(),leaveApi.types()]);rows.value=p.data||[];history.value=h.data||[];types.value=t.data||[]}catch(e){ElMessage.error(e.businessMessage)}finally{loading.value=false}}async function showDetail(row){detail.value=(await leaveApi.detail(row.id)).data;detailVisible.value=true}function openApprove(row,next){current.value=row;action.value=next;comment.value='';approveVisible.value=true}async function submit(){saving.value=true;try{await leaveApi.approve(current.value.id,{action:action.value,comment:comment.value||null});ElMessage.success('审批完成');approveVisible.value=false;await load()}catch(e){ElMessage.error(e.businessMessage)}finally{saving.value=false}}function newType(){Object.assign(typeForm,{name:'',code:'',days_per_year:null});newTypeVisible.value=true}async function saveType(){try{await leaveApi.createType({...typeForm,days_per_year:typeForm.days_per_year===null?null:String(typeForm.days_per_year)});ElMessage.success('类型已创建');newTypeVisible.value=false;await load()}catch(e){ElMessage.error(e.businessMessage)}}onMounted(load)
</script>
